use std::cmp::Reverse;

fn torneo(valores: &Vec<i32>, i: usize, j: usize, k: usize) -> (usize, usize) {
    // We collect the three indices into a small array and sort them
    // in descending order by the values they point to.
    let mut idxs = [i, j, k];
    idxs.sort_by_key(|&idx| Reverse(valores[idx]));
    // After sorting, idxs[0] is the index of the largest value,
    // and idxs[1] is the index of the second‐largest.
    (idxs[0], idxs[1])
}

